      const pair = world ? project.line(a,b) : [a,b];
      if (!pair) return;
      const [start, end] = pair.map(xy);
      const direction = style.units === 'world' && directionBetween(start,end);
      const side = direction ? perpendicular(direction.axis) : undefined;
