    fence: { need: { a: 'vec3', b: 'vec3' }, may: { h: 'pos', bay: 'pos', pickets: 'num' } },
    pipe: { need: { pts: 'pts' }, may: { r: 'pos', wall: 'pos', collar: 'pos' } }
