    automatic: true,
    response: 12,
    blink: { duration: 0.25, close: 0.07, holdEnd: 0.12, open: 0.13, cycle: 14, at: [2.8, 6.9, 10.7, 10.96] },
    gaze: { mode: 'curious', response: 9, amplitude: [0.24, 0.08], frequency: [0.72, 0.51] }
