          q = Math.sqrt(K.hash(seed, i, 2)) * R * 0.85,
          g = [at[0] + Math.cos(a) * q, at[1] + Math.sin(a) * q, sz[0] + (sz[1] - sz[0]) * K.hash(seed, i, 3)];
