            nd: true,
            k,
            ph: B.rr(0, 6.3),
            sp: k === 3 ? B.rr(0.05, 0.12) : B.rr(0.4, 1.1),
            rg: k === 3 ? B.rr(0.6, 1.4) : B.rr(0.03, 0.09),
