          s,
          px,
          unit,
          // a point in the prop's own space (y up, a unit a screen pixel at its size) in the world
          at: (x, y, z) => [q.p[0] + (x * c - z * sn) * unit, q.p[1] + y * unit, q.p[2] + (x * sn + z * c) * unit]
