        S.tube(
          [q.at(-v.len / 2, v.r * 0.85, 0), q.at(v.len / 2, v.r * 0.8, 0)],
          v.r * q.unit,
          v.r * 0.92 * q.unit,
          M.bark,
          { res: res(q) }
        );
