          at,
          cell,
          n,
          names: names.slice(),
          mat,
          T,
          amb,
          sources,
          heaters,
          sinks,
          cols: C,
          sun,
          tool,
          open: open,
          rate: o.rate || 30,
          seed: o.seed || 1,
          mats: o.materials || null,
          baked: baked.some(v => v) ? baked : null
